const items = $input.all();

let students = [];
let invalidJsonItems = 0;

// 1. Parse the JSON strings returned by the LLM
for (const item of items) {
  let data = item.json.text ?? item.json;

  if (typeof data === "string") {
    try {
      data = JSON.parse(data);
    } catch (error) {
      invalidJsonItems++;
      continue;
    }
  }

  if (Array.isArray(data)) {
    students.push(...data);
  } else if (data && typeof data === "object") {
    students.push(data);
  }
}

// 2. Helper functions
function cleanText(value) {
  return typeof value === "string" ? value.trim() : value;
}

function titleCase(value) {
  if (typeof value !== "string") return value;

  return value
    .trim()
    .toLowerCase()
    .replace(/\b([a-z])/g, letter => letter.toUpperCase())
    .replace(/\bMl\b/g, "ML")
    .replace(/\bAi\b/g, "AI")
    .replace(/\bSql\b/g, "SQL");
}

function normalizeFee(value) {
  if (typeof value === "boolean") return value;

  const v = String(value ?? "").trim().toLowerCase();

  if (["yes", "paid", "true", "1"].includes(v)) {
    return true;
  }

  if (["no", "unpaid", "not paid", "false", "0"].includes(v)) {
    return false;
  }

  return null;
}

function normalizePhone(value) {
  if (value === null || value === undefined) return "";

  let phone = String(value).trim();

  // Handle numbers converted to strings such as 9876543210.0
  phone = phone.replace(/\.0$/, "");

  // Remove spaces, hyphens, and parentheses
  phone = phone.replace(/[\s\-()]/g, "");

  // Remove optional Indian country code
  if (phone.startsWith("+91")) {
    phone = phone.slice(3);
  } else if (phone.startsWith("0091")) {
    phone = phone.slice(4);
  } else if (phone.startsWith("91") && phone.length === 12) {
    phone = phone.slice(2);
  }

  return phone;
}

// 3. Track removed records
const stats = {
  received: students.length,
  duplicate: 0,
  invalidEmail: 0,
  invalidPhone: 0,
  invalidFeeStatus: 0,
  kept: 0,
  invalidJsonItems
};

const seenStudentIds = new Set();
const seenEmails = new Set();
const cleanedStudents = [];

// 4. Clean and validate every student
for (const original of students) {
  const student = {};

  // Trim whitespace from every string field
  for (const [key, value] of Object.entries(original)) {
    student[key] = cleanText(value);
  }

  // Standardize selected text fields
  for (const key of ["Name", "Course", "City"]) {
    if (typeof student[key] === "string") {
      student[key] = titleCase(student[key]);
    }
  }

  // Normalize email
  student.Email = String(student.Email ?? "")
    .trim()
    .toLowerCase();

  const emailPattern =
    /^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-z0-9-]+(?:\.[a-z0-9-]+)+$/i;

  if (!emailPattern.test(student.Email)) {
    stats.invalidEmail++;
    continue;
  }

  // Normalize and validate Indian mobile number
  const phone = normalizePhone(student.Phone);

  if (!/^[6-9]\d{9}$/.test(phone)) {
    stats.invalidPhone++;
    continue;
  }

  student.Phone = phone;

  // Normalize fee payment into a real Boolean
  const feeStatus = normalizeFee(student.Fee_Paid);

  if (feeStatus === null) {
    stats.invalidFeeStatus++;
    continue;
  }

  student.Fee_Paid = feeStatus;

  // Remove duplicates using Student_ID, then email
  const studentId = String(student.Student_ID ?? "").trim();

  const duplicate =
    (studentId !== "" && seenStudentIds.has(studentId)) ||
    seenEmails.has(student.Email);

  if (duplicate) {
    stats.duplicate++;
    continue;
  }

  if (studentId !== "") {
    seenStudentIds.add(studentId);
  }

  seenEmails.add(student.Email);
  cleanedStudents.push(student);
}

stats.kept = cleanedStudents.length;

// 5. Return one output item containing the cleaned JSON array
return cleanedStudents.map(student => ({
  json: student
}));
